}

function Get-SafeName {
    param([string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) {
        $Name = "Unnamed"
    }

    $safe = $Name -replace '[\\/:*?"<>|]', '_'
    if ($safe.Length -gt 80) {
        $safe = $safe.Substring(0, 80)
    }

    return $safe.Trim().TrimEnd('.')
}

